using namespace std;

int main() {
    int count[101] = {}, sum = 0, answer = 0;

    for (int i = 0, x; i < 5; ++i) {
        cin >> x;
        sum += x;
        ++count[x];
    }

    for (int x = 1; x <= 100; ++x) {
        if (count[x] >= 2) {
            answer = max(answer, x * min(count[x], 3));
        }
    }

    cout << sum - answer;
    return 0;
}

